  `event_id` varchar(255) DEFAULT NULL,
  `reservation_id` varchar(255) DEFAULT NULL,
  `seat_id` varchar(255) DEFAULT NULL,
  `show_id` varchar(255) DEFAULT NULL,
  `ticket_tier_id` varchar(255) DEFAULT NULL,
  `ticket_type_id` varchar(255) DEFAULT NULL,
