  `check_in_at` datetime(6) DEFAULT NULL,
  `check_in_method` enum('QR_CODE','TICKET_CODE') DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK3yhl9h2vv803mhf1jpk8puq4a` (`seat_id`),
  KEY `FKfytuhjopeamxbt1cpudy92x5n` (`event_id`),
