DROP TABLE IF EXISTS `ticket_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ticket_type` (
  `id` varchar(255) NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `created_by` varchar(255) DEFAULT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `deleted_by` varchar(255) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `queue_no` bigint DEFAULT NULL,
  `reserved_quantity` int DEFAULT NULL,
  `seat_map_svg` longtext,
  `seating_type` enum('SEATED','STANDING') DEFAULT NULL,
  `section_id` varchar(255) DEFAULT NULL,
  `sold_quantity` int DEFAULT NULL,
  `status` enum('ACTIVE','COMING_SOON','DELETED','EXPIRED','INACTIVE','ON_SALE','SOLD_OUT','SUSPENDED','TIER_SOLD_OUT') DEFAULT NULL,
  `total_quantity` int DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `updated_by` varchar(255) DEFAULT NULL,
  `show_id` varchar(255) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `FK5mq5ya784odpp5elkl2hfphby` (`show_id`),
  CONSTRAINT `FK5mq5ya784odpp5elkl2hfphby` FOREIGN KEY (`show_id`) REFERENCES `event_show` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

